export const onContributorCreated = /*#__PURE__*/ EventDefinition(
  'wix.identity.v1.contributor_created',
  true,
  (event: ContributorCreatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'entity.joinedAt' }, { path: 'metadata.eventTime' }],
        },
      ])
    )
)<ContributorCreatedEnvelope>();

